# Static libjq and the bundled Oniguruma, so the binary is one file with no library of
# its own to ship: libjq has no other consumer, and Oniguruma — which jq needs for test,
# match, sub and the other regex builtins — is not something the base has or wants.
# The documentation is generated by a Ruby toolchain, and is off.
./configure \
    --prefix=/usr \
    --disable-shared \
    --enable-static \
    --with-oniguruma=builtin \
    --disable-docs \
    --disable-maintainer-mode
make
install -D -m 755 jq $ROOTFS/usr/bin/jq
assert_not_linked libjq usr/bin/jq
assert_not_linked libonig usr/bin/jq
